    STARTUPINFOA si{};
    si.cb = sizeof(si);
    PROCESS_INFORMATION pi{};

    std::string cmd = "\"" + path + "\"";
    std::vector<char> args(cmd.begin(), cmd.end());
    args.push_back('\0');

    if (!CreateProcessA(nullptr, args.data(), nullptr, nullptr, FALSE, 0, nullptr, nullptr, &si, &pi))
        return false;

    WaitForSingleObject(pi.hProcess, INFINITE);
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);
    return true;
}

int main(int argc, char* argv[])
{
    if (argc < 2)
    {
        std::cerr << "Usage: " << argv[0] << " <URL>\n";
        return 1;
    }

    const std::string url = argv[1];
    if (url.rfind("https://", 0) != 0 && url.rfind("http://", 0) != 0)
    {
        std::cerr << "URL must start with http:// or https://\n";
        return 1;
    }

    char tempPath[MAX_PATH];
    if (!GetTempPathA(MAX_PATH, tempPath))
    {
        std::cerr << "GetTempPath failed\n";
        return 1;
    }

    char tempFileName[MAX_PATH];
    if (!GetTempFileNameA(tempPath, "exe", 0, tempFileName))
    {
        std::cerr << "GetTempFileName failed\n";
        return 1;
    }

    std::string downloadPath(tempFileName);
    if (downloadPath.size() >= 4)
        downloadPath.replace(downloadPath.size() - 4, 4, ".exe");

    if (!DownloadFile(url, downloadPath))
    {
        std::cerr << "Download failed\n";
        DeleteFileA(downloadPath.c_str());
        return 1;
    }

    std::cout << "About to execute downloaded file: " << downloadPath << "\n";
    std::cout << "Type YES to continue: ";
    std::string confirm;
    std::getline(std::cin, confirm);
    if (confirm != "YES")
    {
        std::cout << "Execution cancelled.\n";
        DeleteFileA(downloadPath.c_str());
        return 0;
    }

    if (!ExecuteFile(downloadPath))
    {
        std::cerr << "Execution failed\n";
        DeleteFileA(downloadPath.c_str());
        return 1;
    }

    DeleteFileA(downloadPath.c_str());
    return 0;
}

